src=Path("/opt/android-sdk");dst=Path("/srv/projects/android-sdk")
out={"installation":"android-sdk","status":"BLOCKED","changed":False}
def services():
 names=("ssh","nginx","lowcost-europa","fadego-staging","pink-iptv-backend","pm2-root")
 return {x:subprocess.run(["systemctl","is-active",x],capture_output=True,text=True,timeout=6).stdout.strip() for x in names}
moved=False
try:
 if not src.is_dir() or src.is_symlink() or dst.exists() or dst.is_symlink():raise RuntimeError("source_or_target_preflight")
